const GKEY='rc_gym_v2',main=document.getElementById('main'),catalogId=name=>'ex-'+[...name.toLowerCase()].reduce((n,c)=>(Math.imul(n,31)+c.charCodeAt(0))|0,0).toString(36).replace('-','n');
